insert into public.edital_programas (edital_catalog_id, subject_catalog_id, texto, fonte_url, conferido_em)
select e.id, s.id, v.texto, 'https://sistemas.institutoverbena.ufg.br/2024/concurso-tj-go/sistema/arquivos/editais/RL-EDITAL_TJ_ABERTURA_COMPILADO-2024.pdf', '2026-08-03'
from (values
  ('tj-go-analista-sistemas', 'Língua Portuguesa', '1. Características e funcionalidades de gêneros textuais variados. 2. Interpretação textual de gêneros textuais variados. 3. Modos de enunciação presentes no texto. 4. Gramática normativa. 5. Mecanismos de produção de sentidos nos textos: polissemia, ironia, comparação, ambiguidade, citação, inferência e pressuposto. 6. Organização do texto e fatores de textualidade (coesão, coerência, intertextualidade, informatividade, intencionalidade, aceitabilidade e situacionalidade). 7. Progressão temática. 8. Sequências textuais: descritiva, narrativa, argumentativa, injuntiva e dialogal. 9. Elementos de sequenciação textual: referenciação, substituição, repetição, conectores e outros elementos. 10. Tipos de argumento. 11. Classificação gramatical. 12. Processo de formação de palavras. 13. Análise morfossintática. 14. Fenômenos gramaticais e construção de significados na língua portuguesa. 15. Relações de coordenação entre orações e entre termos da oração. 16. Relações de subordinação entre orações e entre termos da oração. 17. Concordância verbal e nominal. 18. Regência verbal e nominal. 19. Colocação pronominal. 20. Pontuação.'),
  ('tj-go-analista-sistemas', 'Raciocínio Lógico-Matemático', '1. Conjuntos numéricos. 2. Números naturais e números inteiros: operações, relação de ordem, divisibilidade, máximo divisor comum, mínimo múltiplo comum e decomposição em fatores primos. 3. Lógica e raciocínio lógico. 4. Estruturas lógicas. 5. Diagramas lógicos. 6. Lógica de argumentação: analogias, inferências, deduções e conclusões. 7. Lógica sentencial (ou proposicional). 8. Proposições simples e compostas. 9. Tabelas verdade. 10. Tautologia, contradição e contingência. 11. Equivalências e negações. 12. Argumento: abdução, analogia, dedução e indução. 13. Silogismo. 14. Análise combinatória: princípio fundamental da contagem, arranjos, permutações e combinações. 15. Noções de estatística: apresentação de dados estatísticos: tabelas e gráficos e medidas de centralidade (média aritmética, média ponderada, mediana e moda). 16. Noções de probabilidade: experimento aleatório, espaços amostrais finitos e equiprováveis e eventos aleatórios. 17. Regra de três simples e composta. 18. Noções de matemática financeira: razão, proporção, porcentagem, juros simples, juros compostos e descontos simples.'),
  ('tj-go-analista-sistemas', 'Atualidades e Conhecimentos Gerais', '1. Formação social, política, histórica e econômica do Brasil. 2. Direitos humanos. 3. Minorias e etnicidade. 4. Mundo do trabalho. 5. Mobilidade e migrações. 6. Questões atuais do meio ambiente, desastres ambientais e políticas ambientais. 7. Educação: história, desafios e as inovações tecnológicas. 8. Segurança: conflitos sociais, explosão urbana. 9. Cultura: homogeneidade e heterogeneidade no Brasil. 10. Tecnologia e sua influência no meio social. 11. Energia, sustentabilidade e compromisso social. 12. Comunicação em redes: internet e as implicações nas diversas áreas 13. Relações internacionais. 14. Movimentos sociais. 15. Aspectos socioantropológicos da saúde no Brasil e mundo. 16. Religiosidades e as influências sociais e antropológicas das matrizes africana, europeia e indígena. 17. Aspectos histórico-geográficos de Goiás.'),
  ('tj-go-analista-sistemas', 'Legislação (Ética, Improbidade e Licitações)', '1. Ética e função pública. 2. Ética no Setor Público. 3. Lei nº 8.429/1992 e suas alterações. 4. Lei nº 9.784/1999 e suas alterações (processo administrativo). 5. Lei nº 12.527/2011 (Lei de Acesso à Informação). 6. Decreto nº 7.724/2012. 7. Decreto nº 9.830/2019. 8. Princípios fundamentais da Constituição Federal de 1988: direitos e garantias fundamentais; direitos e deveres individuais e coletivos; direitos sociais; da organização do estado (união, estados, municípios, Distrito Federal e territórios); da Administração Pública: dos servidores públicos; da Organização dos Poderes. 9. Princípios de Direito Administrativo. 10. Atos Administrativos: elementos e atributos. 11. Classificações e espécies dos atos administrativos. 12. Anulação, revogação e convalidação dos atos administrativos. 13. Competência. 14. Processos administrativos. 15. Improbidade administrativa. 16. Agentes públicos: agentes políticos e servidores públicos. 17. A nova lei de licitação (Lei n° 14.133/21).'),
  ('tj-go-analista-sistemas', 'Tecnologia da Informação', '1. Fundamentos da computação: componentes e arquiteturas de sistemas computacionais (hardware e software). 2. Representação de dados: binário, hexadecimal e decimal; aritmética computacional. 3. Processamento paralelo e distribuído. 4. Pipeline. 5. Multiprocessamento simétrico e assimétrico. 6. Componentes e arquiteturas de processadores; conjuntos de instrução. 7. Hierarquia de memória. 8. Interface entre processadores e periféricos. 9. Sistemas operacionais: fundamentos dos sistemas operacionais; gerenciamento de processos e fluxos de execução (threads): alocação de CPU, comunicação e sincronização entre processos, impasses (deadlocks) e esgotamento de recursos (starvation). 10. Gerenciamento de memória: alocação, segmentação, memória virtual e paginação. Sistemas de entrada e saída: estruturas de armazenamento secundário e terciário, análise de desempenho e confiabilidade. 11. Noções sobre os sistemas operacionais Ubuntu, Windows 10 e superiores, e Windows Server 2019 e superiores. 12. Conceitos de virtualização, máquinas virtuais, containers e DOCKER. 13. Acessibilidade e engenharia de usabilidade: engenharia de usabilidade: conceitos básicos. 14. Arquitetura da informação: conceitos básicos. 15. Conceitos de usabilidade, comunicabilidade, acessibilidade e navegabilidade. 16. Análise de requisitos de usabilidade. 17. Teste de usabilidade. 18. Concepção, projeto e implementação de interfaces. 19. Projeto de telas e relatórios. 20. Wireframes; recomendações de acessibilidade para a construção e adaptação de conteúdos do governo brasileiro na internet, conforme o Decreto n° 5.296/2004 atualizado. 21. Modelo de acessibilidade proposto pelo Governo Eletrônico Brasileiro (e- MAG). 22. Cartilha técnica proposta pelo Governo Eletrônico Brasileiro. 23. Cartilha de usabilidade para Sítios e Portais do Governo Federal - Projeto Padrões Brasil e-Gov. técnicos para implementação da acessibilidade em HTML (W3C/WAI) e Governo Eletrônico. 24. Fundamentos de programação: lógica de programação (operadores e expressões; estruturas de controle, seleção, repetição e desvio). 25. Estruturas de dados (listas, pilhas, filas, árvores; métodos de ordenação, pesquisa e hashing). 26. Análise de algoritmos e custo computacional (notação Big-O). 27. Paradigmas de programação (programação orientada a objetos e programação funcional). 28. Compiladores e interpretadores; linguagens e ambientes de programação: Java e PHP; Spring Framework (Spring Boot, Spring MVC, Spring Data JPA, Spring Data Envers) Java EE (JSP/Servlets, JPA, JDBC Web Services JAX-RS 2.X) Testes de software. 29. Testes de unitários com JUnit, Spook e Mockito. 30. Testes de integração e testes funcionais. 31. Metodologia de desenvolvimento como TDD e BDD. 32. Programação para dispositivos móveis: Android, IOS. 33. Integração contínua com GitLab CI, Docker Compose, Gradle e NPM. 34. Desenvolvimento de sistemas Web: HTML, CSS3, jQuery, Web Services REST, JavaScript, Angular 1.x, React. 35. Arquitetura de aplicações para ambiente web e portais corporativos: conceitos básicos: colaboração, personalização, gestão do conhecimento, gestão de conteúdo e taxonomia. 36. Servidor de aplicações (JBoss, Wildfly e Tomcat). Servidor Web (Apache, IIS e nginx). 37. Ambientes internet, extranet, intranet e Portal - finalidades, características físicas e lógicas, aplicações e serviços. 38. Arquitetura de software: padrões de projeto ("Java Enterprise Patterns", Gof ("Gang of Four") e POSA ("Pattern-Oriented Software Architecture"), Refatoração e Clean Code. 39. Arquitetura 3 camadas. 40. Padrão MVC. 41. Soluções de integração: Service- Oriented Architecture - SOA, REST e Web Services. 42. Gerenciamento de microserviços utilizando Docker Swarm. 43. Integração contínua e entrega contínua. 44. Engenharia de software: princípios, ciclo de vida (requisitos, análise, projeto, testes e implementação). 45. Ferramentas CASE. 46. Análise e projeto orientado a objetos com UML. 47. Processos de software (Norma ABNT NBR ISO/IEC 12207:2009). 48. Análise de Pontos de Função - APF. Testes de software. 49. Metodologias ágeis: SCRUM, XP, FDD, MDA e MDD. 50. Qualidade de software: CMMI 2.0 e MPS.BR. 51. Linguagens SQL e PL-SQL. 52. Gerenciamento de projetos: PMBOK 6° edição (conceitos, estrutura e objetivos); ciclo de vida de projeto e de produto; processos, grupos de processo e áreas de conhecimento. 53. Gerenciamento de serviços: ITIL v.4. 54. Protocolos de redes de computadores: HTTP, HTTPS, SMTP, IMAP, DNS, DHCP, TCP, UDP, OSPF, BGP, SNMP. 55. Arquitetura TCP/IP; IPv4 e IPv6; endereçamento IP; IPv4, IPv6, VoIP. 56. Redes sem fio: padrão IEEE 802.11 Wireless LAN; gerenciamento de redes: conceitos, fundamentos, protocolos e implantação (SNMP, RMON, MIBs, NMSs, agentes, CiscoView, CiscoWorks, Ethereal e MRTG). 57. Infraestrutura de rede: cabeamento estruturado, VLANs, QoS. 58. Gerenciamento de redes: SNMP, ICMP; monitoramento (Zabbix, Prometheus, Grafana). 59. Software-Defined Networking (SDN): VMware NSX. 60. Redes Overlay: VXLAN.'),
  ('tj-go-contador', 'Língua Portuguesa', '1. Características e funcionalidades de gêneros textuais variados. 2. Interpretação textual de gêneros textuais variados. 3. Modos de enunciação presentes no texto. 4. Gramática normativa. 5. Mecanismos de produção de sentidos nos textos: polissemia, ironia, comparação, ambiguidade, citação, inferência e pressuposto. 6. Organização do texto e fatores de textualidade (coesão, coerência, intertextualidade, informatividade, intencionalidade, aceitabilidade e situacionalidade). 7. Progressão temática. 8. Sequências textuais: descritiva, narrativa, argumentativa, injuntiva e dialogal. 9. Elementos de sequenciação textual: referenciação, substituição, repetição, conectores e outros elementos. 10. Tipos de argumento. 11. Classificação gramatical. 12. Processo de formação de palavras. 13. Análise morfossintática. 14. Fenômenos gramaticais e construção de significados na língua portuguesa. 15. Relações de coordenação entre orações e entre termos da oração. 16. Relações de subordinação entre orações e entre termos da oração. 17. Concordância verbal e nominal. 18. Regência verbal e nominal. 19. Colocação pronominal. 20. Pontuação.'),
  ('tj-go-contador', 'Raciocínio Lógico-Matemático', '1. Conjuntos numéricos. 2. Números naturais e números inteiros: operações, relação de ordem, divisibilidade, máximo divisor comum, mínimo múltiplo comum e decomposição em fatores primos. 3. Lógica e raciocínio lógico. 4. Estruturas lógicas. 5. Diagramas lógicos. 6. Lógica de argumentação: analogias, inferências, deduções e conclusões. 7. Lógica sentencial (ou proposicional). 8. Proposições simples e compostas. 9. Tabelas verdade. 10. Tautologia, contradição e contingência. 11. Equivalências e negações. 12. Argumento: abdução, analogia, dedução e indução. 13. Silogismo. 14. Análise combinatória: princípio fundamental da contagem, arranjos, permutações e combinações. 15. Noções de estatística: apresentação de dados estatísticos: tabelas e gráficos e medidas de centralidade (média aritmética, média ponderada, mediana e moda). 16. Noções de probabilidade: experimento aleatório, espaços amostrais finitos e equiprováveis e eventos aleatórios. 17. Regra de três simples e composta. 18. Noções de matemática financeira: razão, proporção, porcentagem, juros simples, juros compostos e descontos simples.'),
  ('tj-go-contador', 'Atualidades e Conhecimentos Gerais', '1. Formação social, política, histórica e econômica do Brasil. 2. Direitos humanos. 3. Minorias e etnicidade. 4. Mundo do trabalho. 5. Mobilidade e migrações. 6. Questões atuais do meio ambiente, desastres ambientais e políticas ambientais. 7. Educação: história, desafios e as inovações tecnológicas. 8. Segurança: conflitos sociais, explosão urbana. 9. Cultura: homogeneidade e heterogeneidade no Brasil. 10. Tecnologia e sua influência no meio social. 11. Energia, sustentabilidade e compromisso social. 12. Comunicação em redes: internet e as implicações nas diversas áreas 13. Relações internacionais. 14. Movimentos sociais. 15. Aspectos socioantropológicos da saúde no Brasil e mundo. 16. Religiosidades e as influências sociais e antropológicas das matrizes africana, europeia e indígena. 17. Aspectos histórico-geográficos de Goiás.'),
  ('tj-go-contador', 'Legislação (Ética, Improbidade e Licitações)', '1. Ética e função pública. 2. Ética no Setor Público. 3. Lei nº 8.429/1992 e suas alterações. 4. Lei nº 9.784/1999 e suas alterações (processo administrativo). 5. Lei nº 12.527/2011 (Lei de Acesso à Informação). 6. Decreto nº 7.724/2012. 7. Decreto nº 9.830/2019. 8. Princípios fundamentais da Constituição Federal de 1988: direitos e garantias fundamentais; direitos e deveres individuais e coletivos; direitos sociais; da organização do estado (união, estados, municípios, Distrito Federal e territórios); da Administração Pública: dos servidores públicos; da Organização dos Poderes. 9. Princípios de Direito Administrativo. 10. Atos Administrativos: elementos e atributos. 11. Classificações e espécies dos atos administrativos. 12. Anulação, revogação e convalidação dos atos administrativos. 13. Competência. 14. Processos administrativos. 15. Improbidade administrativa. 16. Agentes públicos: agentes políticos e servidores públicos. 17. A nova lei de licitação (Lei n° 14.133/21).'),
  ('tj-go-contador', 'Informática', '1. Família de sistemas operacionais Microsoft Windows para microcomputadores pessoais: interface gráfica do usuário e seus elementos, além da utilização da ajuda e suporte e dos atalhos de teclado. 2. Gerenciamento de arquivos e pastas, incluindo os tipos de arquivos e suas extensões e a pesquisa e localização de conteúdo. 3. Configurações e Painel de Controle, abrangendo a Solução de Problemas. 4. Procedimentos de backup e gerenciamento de impressão. 5. Instalação, desinstalação ou alteração de programas e ativação ou desativação de recursos, incluindo a configuração de aplicativos. 6. Compactação e extração de conteúdo a partir de arquivos zip. 7. Aplicativos pertencentes ao Windows (Bloco de Notas, Paint, WordPad e Mapa de Caracteres). 8. Aplicativos para escritórios por meio de software livre e de software proprietário. 9. Processador de textos (criação, edição e formatação de textos e recursos voltados à automação de documentos). 10. Planilha eletrônica (tipos de dados e referências, criação de planilhas e gráficos, inserindo fórmulas aritméticas e fórmulas baseadas em funções de planilha, configuração de página e impressão, formatação de células e formatação condicional, validação de dados e aplicação de filtros e obtenção de dados de fontes externas. 11. Gerador de apresentação (criação de slides, formatação e inserção de imagens e objetos e efeitos de transição e animações, apresentação de slides e exportação para o formato PDF). 12. Navegadores de Internet, serviços de busca na Web e uso do correio eletrônico. 13. Serviços de correio eletrônico.'),
  ('tj-go-contador', 'Contabilidade Geral', '1. Princípios fundamentais de contabilidade: conceitos e tipos. 2. Noções gerais: conceitos e objetivos da contabilidade, finalidades da contabilidade e campo de atuação. 3. Relatórios gerenciais: periodicidade, comparações orçado/fixado x realizado/executado, consolidação periódica, fonte única ou banco de dados. 4. Patrimônio: bens, direitos e obrigações: conteúdos, classificações e critérios de avaliação. 5. Patrimônio líquido: conceito, estrutura e importância. 6. Variações patrimoniais: conceito e classificação. 7. Gestão: conceito, aspectos econômicos e financeiros; despesas, receitas, resultados e custos. 8. Período administrativo e exercício financeiro. 9. Regimes de caixa e competência. 10. Teoria da escrituração: conceitos e finalidades. 11. A conta: conceito, estrutura, classificação. 12. Método de escrituração: partidas dobradas e princípios. 13. Plano de contas: estrutura do plano de contas. 14. Livros de escrituração. 15. Registro de operações. 16. Depreciações, amortizações e provisões. 17. Balancete de verificação. 18. Encerramento do exercício. 19. Determinação e destinação do crédito. 20. Inventário: conceito e finalidades principais. 21. Classificação do inventário. 22. Avaliação e reavaliação dos bens e demais elementos do patrimônio. 23. Orçamento: conceito e importância; período orçamentário.'),
  ('tj-go-contador', 'Contabilidade Pública', '24. Contabilidade pública: necessidades e serviços públicos; órgãos e funções; organismo público constitucional e organização administrativa; controle interno e controle externo da Administração Pública. 25. A organização dos serviços de contabilidade, relacionamento com o estudo de organização e gestão. 26. O órgão econômico estatal. 27. Controle da contabilidade e auditoria. 28. Organismo financeiro. 29. Patrimônio público; conceituação; estudo qualitativo do patrimônio, substância e contra-substância; patrimônio financeiro e patrimônio permanente; bens públicos; dívida pública e estudo quantitativo do patrimônio público. 30. Processos fundamentais e processos acessórios de gestão. 31. Período administrativo e exercício financeiro; regimes contábeis e gestão financeira. 32. Equilíbrio anual e equilíbrio cíclico. 33. Receita orçamentária e extraorçamentária; despesa orçamentária e despesa extraorçamentária; classificação da receita e da despesa; fases administrativas da receita e da despesa orçamentária superveniência e insubsistência. 34. O regime de adiantamentos. 35. O inventário público; objeto e classificação dos inventários; procedimentos dos inventários e preceitos legais. 36. A escrituração e suas limitações; planos de contas e sistemas de escrituração. 37. As operações de determinação dos resultados financeiros e econômicos do exercício. 38. Balanços orçamentários, financeiro e patrimonial; demonstração das variações, patrimoniais. 39. Prestação e julgamento de contas governamentais.'),
  ('tj-go-oficial-de-justica', 'Língua Portuguesa', '1. Características e funcionalidades de gêneros textuais variados. 2. Interpretação textual de gêneros textuais variados. 3. Modos de enunciação presentes no texto. 4. Gramática normativa. 5. Mecanismos de produção de sentidos nos textos: polissemia, ironia, comparação, ambiguidade, citação, inferência e pressuposto. 6. Organização do texto e fatores de textualidade (coesão, coerência, intertextualidade, informatividade, intencionalidade, aceitabilidade e situacionalidade). 7. Progressão temática. 8. Sequências textuais: descritiva, narrativa, argumentativa, injuntiva e dialogal. 9. Elementos de sequenciação textual: referenciação, substituição, repetição, conectores e outros elementos. 10. Tipos de argumento. 11. Classificação gramatical. 12. Processo de formação de palavras. 13. Análise morfossintática. 14. Fenômenos gramaticais e construção de significados na língua portuguesa. 15. Relações de coordenação entre orações e entre termos da oração. 16. Relações de subordinação entre orações e entre termos da oração. 17. Concordância verbal e nominal. 18. Regência verbal e nominal. 19. Colocação pronominal. 20. Pontuação.'),
